/**
 * 러닝화 DB v3 — 2025~2026 모델년 기준 (마지막 실사: 2026-06)
 *
 * ⚠️ "현행 판매 모델"이라고 쓰지 않는다.
 *
 * 2026-08-28 전수 점검: 52종 중 27종(여성 버전 포함)이 이미 구형이었다.
 * 그전까지 `successor`가 채워진 건 4종뿐이었고, 나머지 23종은 후속작이 나온 줄도
 * 모르고 "추천"하고 있었다. 이 사이트의 유일한 주장이 "광고 아닌 중립 추천"인데,
 * 단종된 모델을 아무 표시 없이 1순위로 올리면 그 주장이 먼저 무너진다.
 *
 * 판정 기준은 **실제 출시 확인**이다. 출시 예정·루머·티저는 후속작으로 치지 않는다.
 * 이 기준 때문에 Adrenaline GTS 26·Revolution 8은 후속으로 표기하지 않았다 —
 * 캘린더에는 존재하는데 출시를 확인하지 못했고, 확인 못 한 것을 채우면
 * 이 필드 전체의 신뢰도가 사라진다. 미확인은 비워두는 쪽이 맞다.
 *
 * 2026-09-01 재점검: 미확인 10종 중 3종을 확인해 채웠다.
 *   GT-2000 14 → 15 (2026-08-01 출시)
 *   Jolt 4 → 5 (아식스 공식 제품 페이지 존재)
 *   SuperComp Elite v4 → v5 (**2025-08-07 출시** — 1년 넘게 구형인 걸 모르고 있었다)
 *
 * 아직 확인 못 한 것 8개 SKU: InfinityRN 4, Revolution 7, Adrenaline GTS 25(남·여),
 *   Cloudrunner 3, 520 v9, KIPRUN KS500 2, Vaporfly 4.
 *   Adrenaline GTS 26은 "2026 Q3 예정"까지만 확인돼 채우지 않았다 — 예정은 출시가 아니다.
 *
 * 2026-09-03: **미확인 8개를 브랜드 공식 도메인으로 전수 확인했다. 남은 미확인 0.**
 *   Revolution 7 → **Revolution 8 (출시 확정)** — nike.com에 정식 제품 페이지·SKU·리뷰·파생 모델
 *   나머지 7개는 후속작이 확인되지 않아 비워둔다. 다만 성격이 둘로 갈린다 —
 *     ① **현행 확정** (공식 사이트에 후속 세대가 없음을 확인):
 *        Vaporfly 4, Cloudrunner 3, InfinityRN 4, KIPRUN KS500 2
 *     ② **판단 보류** (후속 존재 여부를 확정하지 못함):
 *        Adrenaline GTS 25(남·여) — GTS 26이 "2026 Q3 예정"까지만. 예정은 출시가 아니다
 *        520 v9 — newbalance.com에 520v10이 없고, 520이 라이프스타일 라인으로 표기돼 있다
 *   ①과 ②는 `successor`가 똑같이 비어 있지만 뜻이 다르다. 원장에는 날짜만 남으므로
 *   구분이 필요하면 이 주석을 볼 것. 그리고 검색으로 확인할 때 **URL을 추측하지 마라** —
 *   오늘 brooksrunning.com URL을 짐작해서 넣었더니 **Beast GTS 26**이라는 다른 신발로
 *   리다이렉트됐다. 그럴듯한 페이지가 떠서 대충 봤으면 "GTS 26 출시됨"으로 적을 뻔했다.
 *
 * 2026-09-02: **이 주석에 "7종"이라고 적혀 있었는데 실제로는 8개였다.**
 *   Adrenaline GTS 25 여성 버전을 세지 않았다. 모델 단위로 세고 SKU 단위로 관리하니
 *   생긴 어긋남이다. 사람이 주석으로 개수를 관리하면 이렇게 된다 —
 *   그래서 `npm run check:shoes`(scripts/shoe-freshness.mjs)를 만들었다.
 *   확인 날짜는 이제 **lib/shoes/verified.json**이 원장이고, 이 주석은 경위 기록이다.
 *   개수를 알고 싶으면 주석을 읽지 말고 검사기를 돌릴 것.
 *
 * 후속작이 나왔다고 그 신발이 나빠지는 건 아니고 오히려 재고 할인이 붙는다.
 * 그래서 최신작으로 갈아엎지 않고 `successor`만 채운다. 판단은 사용자가 한다.
 * 새 모델을 추가하거나 후속작을 확인했으면 이 주석과 `successor`를 같이 갱신할 것.
 *
 * imageUrl: RunRepeat 사진은 **가로 720px 버전(`-720.jpg`)** 으로 쓴다.
 *   2026-09-28 정정 — 09-26·09-27 에 넣은 64장이 `-main.jpg`(가로 3000px 원본)·`-1440.jpg` 였다. 그 전에 넣은 사진은
 *   원래 720 이었는데 새로 넣으면서 규칙을 몰랐다. 목록 한 화면에 원본 64장이 깔려 크롬 화면 캡처가 30초씩 멈췄다.
 *   64장 모두 720 버전이 뜨는 것을 크롬에서 확인하고 바꿨다(가로 720 으로 로드됨). 새로 넣을 때도 720 으로.
 *
 * priceKrw: 2026년 6월 기준 한국 공식가
 *   2026-09-27 신모델을 넣다가 공식몰 정가가 바뀐 기존 모델을 발견해 고쳤다(화면에 보인 정가, 할인가 아님):
 *     Kinvara 16 185,000→159,000 · Endorphin Speed 5 229,000→219,000 · Triumph 23 225,000→199,000 (saucony.co.kr)
 *     Wave Inspire 22 195,000→169,000 · Wave Sky 9 209,000→189,000 · Wave Rider 29 195,000→169,000 (kor.mizuno.com)
 *     Pegasus 42(남·여) 159,000→169,000 · Pegasus Plus 209,000→219,000 · Alphafly 3 380,000→339,000 ·
 *     Vaporfly 4 369,000→319,000 (nike.com/kr)
 *     (2차, 크롬) 1080 v15 239,000→229,000 · 860 v15 179,000→189,000 (nbkorea.com) · Adizero Boston 12 220,000→179,000 (adidas.co.kr)
 *     (09-28, 크롬) Adizero Adios Pro 4 360,000→299,000 (adidas.co.kr 「Price」 표기, 할인가 아님 — 후속 Adios Pro 5 는 339,000)
 *   09-28 에 아식스 기존 모델도 찾아봤다 — 카야노 32·님버스 27·GT-2000 14·노바블라스트 5 는 한국몰 검색에 **안 나온다**(내려감).
 *   가격을 대조할 수 없어 6월 값 그대로 둔다. 뉴발란스 레벨 v4·SC 엘리트 v4, 아디다스 울트라부스트 25 도 같은 이유로 그대로.
 *   **나머지는 이날 다시 보지 않았다** — 호카는 공식몰 인증서 오류로 못 보고, 온·뉴발란스·푸마·아디다스·아식스의
 *   기존 모델은 위에 적은 것 말고는 대조하지 않았다.
 *   6월 값이 그대로 남아 있을 수 있으니 전수 재확인이 필요하다.
 *   (09-28, check:links:kr 첫 실행) 브룩스 글리세린 22(남·여) 199,000→209,000 — 공식몰 취소선 정가. 아울렛가 167,200 은 할인가라 안 씀
 *   (09-28, hyun 님 캡처 + 크롬) 호카 — 한국 공식몰이 없다(hoka.co.kr 인증서가 다른 도메인 것, hokaoneone.co.kr 도메인 없음,
 *   hoka.com 에 한국 페이지 없음). 그래서 **무신사 호카 판매가(할인 표시 없는 값)** 로 대조했다:
 *     Bondi 9·Bondi 9 Wide 239,000→229,000 · Mach 6 189,000→185,000 · Clifton 10(남·여)·Arahi 8 199,000 그대로 맞음.
 *     참고로 KREAM 「발매가」는 본디 9 와이드 219,000(25/01/15 발매) — 발매 뒤 1만 원 오른 것으로 보인다.
 *     Rocket X 2 는 무신사에 없고 KREAM 발매가가 $250(약 338,000원) 환산값이라 한국 정가가 아니다 — 340,000 그대로, 병행수입 표기 유지.
 *   같은 날 카본 표기도 둘 고쳤다: Pegasus Plus(플레이트 없음), Adizero Boston 12(유리섬유 EnergyRods) → hasCarbon false.
 * primaryBodyTypes: 각 신발이 최적인 체형 (1~3개)
 *
 * 체형 분류:
 *   small_light  키≤163 / ≤55kg
 *   small_mid    키≤163 / 56-75kg
 *   small_heavy  키≤163 / 76kg+
 *   mid_light    키164-177 / ≤60kg
 *   mid_mid      키164-177 / 61-80kg
 *   mid_heavy    키164-177 / 81kg+
 *   tall_mid     키178+ / ≤85kg
 *   tall_heavy   키178+ / 86kg+
 */

