  // ─────────────────────────────────────────────────────────────
  // 2026-09-27 추가 33종 — 57 → 90. 「경쟁 사이트처럼 100개 가까이」 요청.
  //
  // 넣은 기준: **스펙(RunRepeat 실측)과 한국 공식 정가가 둘 다 확인된 것만.** 하나라도 못 읽으면 뺐다.
  //   · 무게·뒤꿈치 스택: RunRepeat 실측(lab). 2026-09-27 각 페이지 실측표에서 읽음(WebFetch)
  //   · 드롭: 브랜드 표기값 (RunRepeat 스펙표의 브랜드 값)
  //   · priceKrw: 한국 공식몰 정가, 2026-09-27 화면 — 아식스 asics.co.kr · 브룩스 brooksrunning.co.kr ·
  //     써코니 saucony.co.kr(운영 조이웍스) · 미즈노 kor.mizuno.com · 나이키 nike.com/kr. 할인가는 쓰지 않음
  //     (아식스 5종은 2026-09-26 에 읽은 값 — 아식스 목록은 스크립트로 그려져서 09-27 에는 다시 확인하지 못함)
  //   · imageUrl: RunRepeat 대표 이미지. 33장 모두 WebFetch 가 「이미지 응답」을 돌려줌을 확인
  //     (일부러 틀린 주소는 404 로 갈려서, 존재 확인으로는 쓸 수 있다. 사진 속 모델이 맞는지는 사람이 볼 것)
  //   · cushioning·uses·stability: 스펙이 아니라 우리 분류. 규칙을 하나로 고정했다 —
  //       전작이 DB 에 있으면 → 전작과 같게 (님버스 28 ← 27 등 11종)
  //       없으면 → cushioning 은 뒤꿈치 스택이 가장 가까운 기존 모델 값(동률이면 다수값, 그래도 같으면 낮은 값),
  //                uses 는 RunRepeat 스펙표 「Pace」 를 그대로 옮김 (Daily running→daily, Tempo→tempo, Competition→racing)
  //       RunRepeat 에는 「장거리」 분류가 없어서, 전작이 없는 신발엔 long 을 붙이지 않았다 — 추측으로 채우지 않음
  //   · hasCarbon: RunRepeat 플레이트 표기가 카본일 때만 true. 리벨리온 프로 3 은 「카본 섬유를 섞은 나일론」이라 false
  //   · 판단 필드 4개는 비워 둠 → 목록·상세·검색에만 나오고 맞춤 추천에는 안 나옴
  //
  // 이날 크롬이 끊겨 못 넣은 브랜드(온·뉴발란스·푸마·아디다스·아식스 일부)는 같은 날 2차로 넣었다 — 아래 2차 머리 주석 참고.
